using System;
using System.Linq;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class PopulationChecks {
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){
  var state=new SliceState{resources=new ResourceState{wheat=7,wood=11},tools=new ToolTechnologyState(),families=new FamilyState(),relationships=VillagePopulation.Create(VillagePopulation.Social)};
  Array.Resize(ref state.resources.cargo,3);Array.Resize(ref state.tools.learners,3);Array.Resize(ref state.families.adults,3);Array.Resize(ref state.relationships,3);
  state.relationships[0].trust=.91f;for(int i=0;i<3;i++)state.tools.Practice(0,1);state.resources.resin=3;Require(state.tools.Craft(state.resources,0,VillageTool.BoundAxe),"Cannot stage legacy tool");state.resources.Ensure("legacy-tree",VillageResource.Wood);state.resources.Harvest(2,"legacy-tree",3);Require(state.Valid(),"Legacy three-adult save rejected");
  var saved=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(state));Require(saved.Valid(),"Legacy round trip failed");var oldActor=saved.relationships[0];var oldCargo=saved.resources.cargo[2];var oldTraits=saved.families.adults[1];saved.Social(5);var resources=saved.Resources;var tools=saved.Tools;var family=saved.Families;
  Require(saved.relationships.Length==6&&resources.cargo.Length==6&&tools.learners.Length==6&&family.adults.Length==6&&saved.Valid(),"Migration did not safely expand records");Require(saved.relationships[0]==oldActor&&saved.relationships[0].trust==.91f&&resources.cargo[2]==oldCargo&&oldCargo.amount==3&&family.adults[1]==oldTraits&&tools.learners[0].axeOwned&&resources.wheat==7&&resources.wood==9,"Migration overwrote original progress");Require(!tools.learners[5].axeOwned&&resources.cargo[5].amount==0,"Migration granted new actor free equipment/cargo");
  for(int i=0;i<3;i++)tools.Practice(5,2);Require(tools.learners[5].hoeKnown&&tools.Craft(resources,5,VillageTool.CultivatingHoe)&&tools.Valid(),"Sixth villager cannot learn/craft independently");Require(family.FormHousehold(4,5,10)&&family.Valid(),"New identities cannot form a household");family.bond=.9f;family.clock=300;Require(family.TryBirth(10,1)&&family.children[0].parentA==4&&family.children[0].parentB==5&&family.Valid(),"New parent identities lost child lineage");Require(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(saved)).Valid(),"Six-adult save invalid");
  var food=new ResourceState{wheat=48};food.Consume(90,9);Require(food.wheat==39&&food.consumed==9&&VillageResources.ReserveTarget(9,48)==39,"Large population food demand was capped at six");var corrupt=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(saved));Array.Resize(ref corrupt.resources.cargo,4);Require(!corrupt.Valid(),"Unexpected roster length accepted");Debug.Log("BWVR_POPULATION_MODEL_PASS: legacy progress/cargo migration, sixth learner/crafter, new parent lineage, nine-person food and bounded saves");
 }
 [MenuItem("BWVR/Verify expanded village population (Play mode)")]
 public static void Verify(){VerifyModel();Require(Application.isPlaying,"Enter Play mode");var w=UnityEngine.Object.FindAnyObjectByType<VillageResources>();Require(w.Gatherers.Length==6,"Starting village does not have six adults");var ids=w.Gatherers.Select(a=>a.GetComponent<VillagerIdentity>()).ToArray();Require(ids.All(i=>i!=null)&&ids.Select(i=>i.Index).Distinct().Count()==6&&ids.Count(i=>i.Gender==VillagerGender.Man)==3&&ids.Count(i=>i.Gender==VillagerGender.Woman)==3,"Roster identity or gender balance invalid");
  foreach(var actor in w.Gatherers){var id=actor.GetComponent<VillagerIdentity>().Index;var animator=actor.GetComponentInChildren<Animator>();Require(animator!=null&&animator.isHuman&&animator.avatar.isValid,"Missing rig for actor "+id);Require(actor.GetComponent<HybridTarget>().id=="villager-"+id&&actor.GetComponent<VillagerAffect>()!=null,"Missing stable target or affect icon");Require(Enum.IsDefined(typeof(VillagerRoutine.Role),actor.GetComponent<VillagerRoutine>().role),"Invalid job role");Require(w.Season.Social(id).Valid(),"Invalid personal social memory");}
  var discoveries=w.GetComponentInParent<QuestSlice>().GetComponentInChildren<IslandDiscoveries>();var point=discoveries.points[0];int visitors=point.Record.visitors;try{point.Record.visitors=0;Require(point.Unseen(6)&&point.Discover(6)&&!point.Discover(6)&&!point.Unseen(7)&&point.Record.visitors==64&&w.Season.Valid(),"Newcomer discovery identity or visitor-save mask invalid");}finally{point.Record.visitors=visitors;}
  var god=w.GetComponentInParent<QuestSlice>().GetComponentInChildren<CreatureHybrid>();Require(god.Find("object-3")?.affordance?.kind==CreatureAffordance.Kind.Food&&god.Find("water")!=null,"Legacy food/water target binding lost");
  Require(w.Gatherers.Count(a=>a.GetComponent<VillagerRoutine>().role==VillagerRoutine.Role.WaterGatherer)==1,"Expansion multiplied water jobs");Require(w.Season.Resources.cargo.Length==6&&w.Season.Tools.learners.Length==6&&w.Season.Families.adults.Length==6&&w.Season.Valid(),"Live population state incomplete");Debug.Log("BWVR_POPULATION_RUNTIME_PASS: six humanoid adults, three men/three women, stable IDs, icons, one water job, complete saved records");
 }
}
}
